import {copy} from './music.js';
import {planProjectLength} from './project-length.js';
const $=s=>document.querySelector(s);
export function createLengthUI({getProject,getRevision,commit,protectedChange,modal,toast}){
 return function showLength(bars){const before=copy(getProject()),at=getRevision();if(bars===before.bars)return;const expanding=bars>before.bars;let result;
  modal(expanding?'延长工程 · 新区域怎么安排':'缩短工程 · 先看会裁掉什么',`<div class="length-form"><p>从 <strong>${before.bars}</strong> 到 <strong>${bars}</strong> 小节。只调整歌曲长度，不改变速度、调性、乐器、音色或混音。</p>${expanding?'<label class="modal-label" for="length-fill">新增部分</label><select id="length-fill"><option value="blank">留空白 · 我来安排段落（默认）</option><option value="repeat">重复现有内容 · 新音块独立编辑</option></select>':'<p>超出新终点的音块、音符与段落会移除或裁短。请看下方预览；取消不改动，应用前保存旧版。</p>'}<div id="length-summary" class="section-summary"></div><div class="modal-notice">留白不复制任何音符。重复会按原工程跨度复制所有轨道的内容和空隙，不是重新编曲；新副本独立，原共享引用和库保持。段落标签不会自动重复。练习范围保持原位置，缩短时裁到新边界，必要时清除。<br>更长工程的 WAV 文件更大，渲染可能耗时；只离线渲染，不播放。整个工程仍受 16 轨、每轨 4000 / 总 12000 音符及本机存储容量限制。</div><div id="length-error" class="export-progress" role="status"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="length-apply">应用长度，不播放</button>');
  const update=()=>{try{result=planProjectLength(before,bars,{fill:$('#length-fill')?.value||'blank'});const r=result.report;$('#length-summary').innerHTML=`<span class="eyebrow">静音长度预览</span><h3>${bars} 小节 · 约 ${Math.round(r.seconds)} 秒</h3><div class="performance-badges"><span>新增 ${r.addedClips} 块 / ${r.addedNotes} 音符</span><span>移除 ${r.removedClips} 块 / ${r.removedNotes} 音符</span><span>裁短 ${r.shortenedClips} 块 / ${r.shortenedNotes} 音符</span><span>独立化 ${r.detached} 个原共享块</span><span>移除 ${r.sectionsRemoved} / 裁短 ${r.sectionsTrimmed} 段落</span></div><p>${r.rangeChanged?'练习范围也会裁剪或清除。':'练习范围不变。'}${expanding&&r.fill==='blank'?'原有音乐精确保留，新增区域仅留白。':''}当前工程尚未改变。</p>`;$('#length-error').textContent='';$('#length-apply').disabled=false}catch(e){result=null;$('#length-summary').textContent='放不下这次变化，当前工程没有改变。';$('#length-error').textContent=e.message;$('#length-apply').disabled=true}};
  if($('#length-fill'))$('#length-fill').oninput=update;const guard=()=>{if(at!==getRevision()){$('#length-error').textContent='工程已改变，请关闭后重新调整长度。';$('#length-apply').disabled=true;return false}return true};$('#length-apply').onclick=()=>{if(!result||!guard())return;protectedChange(()=>{if(!guard())return;if(commit(result.project)){$('#modal').close();toast(`工程已调整为 ${bars} 小节，可一次撤销。没有开始播放。`)}},'调整工程长度前')};update();
 }
}
